import{_ as i,a0 as p,w as u,s as S,ao as e,I as r,a1 as o,A as n,x as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Linux 黑話解釋：什麼是 FOSS（自由和開源軟件）？什麼是開源？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux 黑話解釋：什麼是 FOSS（自由和開源軟件）？什麼是開源？ | LCTT (202010) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 黑話解釋：什麼是 FOSS（自由和開源軟件）？什麼是開源？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 黑話解釋：什麼是 FOSS（自由和開源軟件）？什麼是開源？ | LCTT (202010) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202010/20200926 Linux Jargon Buster- What is FOSS (Free and Open Source Software)- What is Open Source","title":"Linux 黑話解釋：什麼是 FOSS（自由和開源軟件）？什麼是開源？","tag":"202010","desc":""},"relativePath":"202010/20200926 Linux Jargon Buster- What is FOSS (Free and Open Source Software)- What is Open Source.md","filePath":"[post].md"}'),a={name:"202010/20200926 Linux Jargon Buster- What is FOSS (Free and Open Source Software)- What is Open Source.md"};function f(d,t,m,O,F,x){const l=p("Link");return u(),S("div",null,[t[35]||(t[35]=e('<h1 id="linux-黑話解釋-什麼是-foss-自由和開源軟件-什麼是開源" tabindex="-1">Linux 黑話解釋：什麼是 FOSS（自由和開源軟件）？什麼是開源？ <a class="header-anchor" href="#linux-黑話解釋-什麼是-foss-自由和開源軟件-什麼是開源" aria-label="Permalink to “Linux 黑話解釋：什麼是 FOSS（自由和開源軟件）？什麼是開源？”">​</a></h1><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/09/what-is-foss.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>什麼是 FOSS？</p><p>在過去，我曾多次被問到這個問題，現在是時候解釋一下什麼是 Linux 和軟件世界中的 FOSS 了。</p><p>這個區別很重要，因為 FOSS 是一個通用的詞彙，它可以根據上下文的不同而有不同的含義。在這裏，我討論的是軟件中的 FOSS 原則。</p><h3 id="什麼是-foss" tabindex="-1">什麼是 FOSS？ <a class="header-anchor" href="#什麼是-foss" aria-label="Permalink to “什麼是 FOSS？”">​</a></h3><p>FOSS 是指<ruby>自由和開放源碼軟件<rt>Free and Open Source Software</rt></ruby>。這並不意味着軟件是免費的。它意味着軟件的源代碼是開放的，任何人都可以自由使用、研究和修改代碼。這個原則允許人們像一個社區一樣為軟件的開發和改進做出貢獻。</p><h4 id="foss-的起源" tabindex="-1">FOSS 的起源 <a class="header-anchor" href="#foss-的起源" aria-label="Permalink to “FOSS 的起源”">​</a></h4><p>在上世紀 60、70 年代，計算機以硬件為主，硬件價格昂貴。它們主要由大學的學者或實驗室的研究人員使用。以前有限的軟件都是免費的，或者是帶有它們的源代碼，用户可以根據自己的需要修改源代碼。</p><p>在上世紀 70 年代末和 80 年代初，製造商為了不讓自己的軟件在競爭對手的計算機上運行，停止了分發源代碼。</p><p>這種限制性的許可導致了那些習慣和喜歡修改軟件的人的不便和不喜。上世紀 80 年代中期，Richard Stallman 發起了<ruby>自由軟件運動<rt>Free Software Movement</rt></ruby>。</p>',11)),r("p",null,[o(l,{href:"https://www.gnu.org/philosophy/free-sw.html"},{default:n(()=>[...t[0]||(t[0]=[s("Stallman 指明瞭一個軟件要成為 FOSS 的四個基本自由",-1)])]),_:1}),t[1]||(t[1]=s("。",-1))]),t[36]||(t[36]=r("p",null,[r("img",{src:"https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/09/foss-freedoms.jpg?resize=800%2C671&ssl=1",alt:"自由軟件自由"})],-1)),t[37]||(t[37]=r("p",null,"為了便於理解，我將它們重新表述：",-1)),t[38]||(t[38]=r("ul",null,[r("li",null,"任何用户應能為任何目的運行軟件。"),r("li",null,"用户應能自由查看軟件的源代碼，如有需要，應允許用户修改代碼。"),r("li",null,"用户應能自由地將軟件的副本分發給他人。"),r("li",null,"如果用户修改了代碼，她/他應該可以自由地將修改後的代碼發佈給他人。修改後的代碼必須開放源代碼。")],-1)),r("p",null,[t[3]||(t[3]=s("如果有興趣，我建議閲讀這篇關於 ",-1)),o(l,{href:"https://itsfoss.com/history-of-foss/"},{default:n(()=>[...t[2]||(t[2]=[s("FOSS 的歷史",-1)])]),_:1}),t[4]||(t[4]=s("的文章。",-1))]),t[39]||(t[39]=e('<h3 id="foss-中的-free-並不意味着免費" tabindex="-1">FOSS 中的 “Free” 並不意味着免費 <a class="header-anchor" href="#foss-中的-free-並不意味着免費" aria-label="Permalink to “FOSS 中的 “Free” 並不意味着免費”">​</a></h3><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/09/think-free-speech-not-free-beer.jpg?resize=800%2C800&amp;ssl=1" alt=""></p><p>你可能已經注意到了，自由和開源軟件中的 “Free” 並不意味着它是免費的，它意味着運行、修改和分發軟件的“自由”。</p><p>人們經常錯誤地認為，FOSS 或開源軟件不能有價格標籤。這是不正確的。</p><p>大多數 FOSS 都是免費提供的，原因有很多：</p><ul><li>源代碼已經向公眾開放，所以一些開發者認為沒有必要在下載軟件時貼上價格標籤。</li><li>有些項目是由一些志願者免費提供的。因此，主要的開發者認為對這麼多人免費貢獻的東西收費是不道德的。</li><li>有些項目是由較大的企業或非營利組織支持和/或開發的，這些組織會僱傭開發人員在他們的開源項目上工作。</li><li>有些開發者創建開源項目是出於興趣，或者出於他們對用代碼為世界做貢獻的熱情。對他們來説，下載量、貢獻和感謝的話比金錢更重要。</li></ul><p>為了避免強調 “免費”，有些人使用了 FLOSS 這個詞（LCTT 譯註：有時候也寫作 F/LOSS）。FLOSS 是<ruby>自由和開源軟件<rt>Free/Libre Open Source Software</rt></ruby>的縮寫。單詞 Libre（意為自由）與 gartuit/gratis（免費）不同。</p><blockquote><p>“Free” 是言論自由的自由，而不是免費啤酒的免費。</p></blockquote><h3 id="foss-項目如何賺錢" tabindex="-1">FOSS 項目如何賺錢？ <a class="header-anchor" href="#foss-項目如何賺錢" aria-label="Permalink to “FOSS 項目如何賺錢？”">​</a></h3>',9)),r("p",null,[t[6]||(t[6]=s("開源項目不賺錢是一個神話。紅帽是第一個達到 10 億美元大關的開源公司。",-1)),o(l,{href:"https://itsfoss.com/ibm-red-hat-acquisition/"},{default:n(()=>[...t[5]||(t[5]=[s("IBM 以 340 億美元收購了紅帽",-1)])]),_:1}),t[7]||(t[7]=s("。這樣的例子有很多。",-1))]),t[40]||(t[40]=r("p",null,"許多開源項目，特別是企業領域的項目，都會提供收費的支持和麪向企業的功能。這是紅帽、SUSE Linux 和更多此類項目的主要商業模式。",-1)),t[41]||(t[41]=r("p",null,"一些開源項目，如 Discourse、WordPress 等，則提供其軟件的託管實例，並收取一定的費用。",-1)),r("p",null,[t[9]||(t[9]=s("許多開源項目，特別是桌面應用程序，依靠捐贈。VLC、GIMP、Inkscape 等這類開源軟件就屬於這一類。有",-1)),o(l,{href:"https://itsfoss.com/open-source-funding-platforms/"},{default:n(()=>[...t[8]||(t[8]=[s("資助開源項目的方法",-1)])]),_:1}),t[10]||(t[10]=s("，但通常，你會在項目網站上找到捐贈鏈接。",-1))]),t[42]||(t[42]=e('<p>利用開源軟件賺錢可能很難，但也不是完全不可能。</p><h3 id="但我不是程序員-我為什麼要關心一個軟件是否開源" tabindex="-1">但我不是程序員，我為什麼要關心一個軟件是否開源？ <a class="header-anchor" href="#但我不是程序員-我為什麼要關心一個軟件是否開源" aria-label="Permalink to “但我不是程序員，我為什麼要關心一個軟件是否開源？”">​</a></h3><p>這是一個合理的問題。你不是一個軟件開發者，只是一個普通的計算機用户。即使軟件的源代碼是可用的，你也不會理解程序的工作原理。</p><p>這很好。你不會明白，但有必要技能的人就會明白，這才是最重要的。</p><p>你可以這樣想。也許你不會理解一份複雜的法律文件。但如果你有看文件的自由，並保留一份副本，你就可以諮詢某個人，他可以檢查文件中的法律陷阱。</p><p>換句話説，開源軟件具有透明度。</p><h3 id="foss-與開源之間的區別是什麼" tabindex="-1">FOSS 與開源之間的區別是什麼？ <a class="header-anchor" href="#foss-與開源之間的區別是什麼" aria-label="Permalink to “FOSS 與開源之間的區別是什麼？”">​</a></h3><p>你會經常遇到 FOSS 和<ruby>開源<rt>Open Source</rt></ruby>的術語。它們經常被互換使用。</p><p>它們是同一件事嗎？這很難用“是”和“不是”來回答。</p><p>你看，FOSS 中的“Free”一詞讓很多人感到困惑，因為人們錯誤地認為它是免費的。企業高管、高層和決策者往往會關注自由和開源中的“免費”。由於他們是商業人士，專注於為他們的公司賺錢，“自由”一詞在採用 FOSS 原則時起到了威懾作用。</p>',10)),r("p",null,[t[14]||(t[14]=s("這就是為什麼在上世紀 90 年代中期創立了一個名為",-1)),r("ruby",null,[o(l,{href:"https://opensource.org/"},{default:n(()=>[...t[11]||(t[11]=[s("開源促進會",-1)])]),_:1}),t[12]||(t[12]=r("rt",null,"Open Source Initiative",-1))]),t[15]||(t[15]=s("的新組織。他們從自由和開放源碼軟件中去掉了“自由”一詞，並創建了自己的",-1)),o(l,{href:"https://opensource.org/osd"},{default:n(()=>[...t[13]||(t[13]=[s("開放源碼的定義",-1)])]),_:1}),t[16]||(t[16]=s("，以及自己的一套許可證。",-1))]),t[43]||(t[43]=r("p",null,[s("“"),r("ruby",null,[s("開源"),r("rt",null,"Open Source")]),s("”一詞在軟件行業特別流行。高管們對開源更加適應。開源軟件的採用迅速增長，我相信 “免費”一詞的刪除確實起到了作用。")],-1)),t[44]||(t[44]=r("h3",{id:"有問題嗎",tabindex:"-1"},[s("有問題嗎？ "),r("a",{class:"header-anchor",href:"#有問題嗎","aria-label":"Permalink to “有問題嗎？”"},"​")],-1)),r("p",null,[t[18]||(t[18]=s("這正如我在",-1)),o(l,{href:"https://itsfoss.com/what-is-linux-distribution/"},{default:n(()=>[...t[17]||(t[17]=[s("什麼是 Linux 發行版",-1)])]),_:1}),t[19]||(t[19]=s("一文中所解釋的那樣，FOSS/開源的概念在 Linux 的發展和普及中起到了很大的作用。",-1))]),t[45]||(t[45]=r("p",null,"我試圖在這篇黑話解釋文章中用更簡單的語言解釋 FOSS 和開源的概念，而試圖避免在細節或技術精度上做過多的闡述。",-1)),t[46]||(t[46]=r("p",null,"我希望你現在對這個話題有了更好的理解。如果你有問題或建議，歡迎留言並繼續討論。",-1)),t[47]||(t[47]=r("hr",null,null,-1)),r("p",null,[t[21]||(t[21]=s("via: ",-1)),o(l,{href:"https://itsfoss.com/what-is-foss/"},{default:n(()=>[...t[20]||(t[20]=[s("https://itsfoss.com/what-is-foss/",-1)])]),_:1})]),r("p",null,[t[26]||(t[26]=s("作者：",-1)),o(l,{href:"https://itsfoss.com/author/abhishek/"},{default:n(()=>[...t[22]||(t[22]=[s("Abhishek Prakash",-1)])]),_:1}),t[27]||(t[27]=s(" 選題：",-1)),o(l,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[23]||(t[23]=[s("lujun9972",-1)])]),_:1}),t[28]||(t[28]=s(" 譯者：",-1)),o(l,{href:"https://github.com/wxy"},{default:n(()=>[...t[24]||(t[24]=[s("wxy",-1)])]),_:1}),t[29]||(t[29]=s(" 校對：",-1)),o(l,{href:"https://github.com/wxy"},{default:n(()=>[...t[25]||(t[25]=[s("wxy",-1)])]),_:1})]),r("p",null,[t[32]||(t[32]=s("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[30]||(t[30]=[s("LCTT",-1)])]),_:1}),t[33]||(t[33]=s(" 原創編譯，",-1)),o(l,{href:"https://linux.cn/"},{default:n(()=>[...t[31]||(t[31]=[s("Linux中國",-1)])]),_:1}),t[34]||(t[34]=s(" 榮譽推出",-1))])])}const w=i(a,[["render",f]]);export{L as __pageData,w as default};
